package tests

import (
	"context"
	"errors"
	"fmt"
	"io"
	"net/http"
	"strings"
	"testing"

	"exercise/src/feedsync"
)

const (
	lineA = `{"sku":"A-1","price_cents":100}` + "\n"
	lineB = `{"sku":"B-2","price_cents":250}` + "\n"
	lineC = `{"sku":"C-3","price_cents":999}` + "\n"
)

type countingBody struct {
	r      io.Reader
	read   int64
	closed *int
}

func (b *countingBody) Read(p []byte) (int, error) {
	n, err := b.r.Read(p)
	b.read += int64(n)
	return n, err
}

func (b *countingBody) Close() error { *b.closed++; return nil }

type endless struct{}

func (endless) Read(p []byte) (int, error) {
	for i := range p {
		p[i] = 'x'
	}
	return len(p), nil
}

type fakeDoer struct {
	status int
	body   io.Reader
	last   *countingBody
	closed int
}

func (d *fakeDoer) Do(req *http.Request) (*http.Response, error) {
	d.last = &countingBody{r: d.body, closed: &d.closed}
	return &http.Response{StatusCode: d.status, Body: d.last}, nil
}

func newCatalog(body io.Reader, max int64) (*feedsync.Catalog, *fakeDoer) {
	d := &fakeDoer{status: 200, body: body}
	return feedsync.NewCatalog(&feedsync.Fetcher{Client: d, MaxBytes: max}), d
}

func TestSyncSmallFeed(t *testing.T) {
	c, _ := newCatalog(strings.NewReader(lineA+lineB+lineC), 1<<20)
	n, err := c.Sync(context.Background(), "http://supplier/feed")
	if err != nil || n != 3 {
		t.Fatalf("want 3 items and no error, got %d, %v", n, err)
	}
	if p, ok := c.Price("B-2"); !ok || p != 250 {
		t.Fatalf("price of B-2: got %d, %v", p, ok)
	}
}

func TestFeedExactlyAtLimitIsAccepted(t *testing.T) {
	feed := lineA + lineB + lineC
	c, _ := newCatalog(strings.NewReader(feed), int64(len(feed)))
	n, err := c.Sync(context.Background(), "http://supplier/feed")
	if err != nil || n != 3 {
		t.Fatalf("a feed of exactly MaxBytes must be accepted, got %d, %v", n, err)
	}
}

func TestFeedOneByteOverTheLimitIsRejected(t *testing.T) {
	feed := lineA + lineB + lineC
	c, _ := newCatalog(strings.NewReader(feed), int64(len(feed)-1))
	_, err := c.Sync(context.Background(), "http://supplier/feed")
	if !errors.Is(err, feedsync.ErrTooLarge) {
		t.Fatalf("want ErrTooLarge for a feed 1 byte over the limit, got %v", err)
	}
}

func TestOversizeFeedCutOnLineBoundaryIsNotAppliedPartially(t *testing.T) {
	feed := lineA + lineB + lineC
	c, _ := newCatalog(strings.NewReader(feed), int64(len(lineA+lineB)))
	n, err := c.Sync(context.Background(), "http://supplier/feed")
	if err == nil {
		t.Fatalf("sync reported success with %d of 3 products: the rest was silently dropped", n)
	}
	if c.Len() != 0 {
		t.Fatalf("catalog must stay empty after a rejected feed, has %d items", c.Len())
	}
}

func TestRejectedSyncKeepsPreviousCatalog(t *testing.T) {
	c, d := newCatalog(strings.NewReader(lineA+lineB+lineC), 1<<20)
	if _, err := c.Sync(context.Background(), "u"); err != nil {
		t.Fatal(err)
	}
	d.body = strings.NewReader(lineB + lineC + lineA + lineB)
	c.Fetcher.MaxBytes = int64(len(lineB + lineC))
	if _, err := c.Sync(context.Background(), "u"); err == nil {
		t.Fatal("oversize feed should be an error")
	}
	if _, ok := c.Price("A-1"); !ok || c.Len() != 3 {
		t.Fatalf("previous catalog must survive, has %d items", c.Len())
	}
}

func TestEndlessBodyIsBoundedAndRejected(t *testing.T) {
	const max = 64 * 1024
	c, d := newCatalog(endless{}, max)
	_, err := c.Sync(context.Background(), "http://supplier/feed")
	fmt.Printf("endless body: read %d bytes with MaxBytes=%d, err=%v\n", d.last.read, int64(max), err)
	if !errors.Is(err, feedsync.ErrTooLarge) {
		t.Fatalf("want ErrTooLarge, got %v", err)
	}
	if d.last.read > max+1 {
		t.Fatalf("read %d bytes, more than MaxBytes+1", d.last.read)
	}
}

func TestNon200IsAnError(t *testing.T) {
	c, d := newCatalog(strings.NewReader("oops"), 1024)
	d.status = 503
	if _, err := c.Sync(context.Background(), "u"); err == nil {
		t.Fatal("503 must be an error")
	}
}

func TestBodyAlwaysClosed(t *testing.T) {
	c, d := newCatalog(strings.NewReader(lineA), 1024)
	c.Sync(context.Background(), "u")
	if d.closed != 1 {
		t.Fatalf("body closed %d times, want 1", d.closed)
	}
}
